from vc_kit import *

def B(say, scene, *cuts, **k):
    b = dict(say=say, scene=scene, do=[{'on': w, 'scene': sc} for w, sc in cuts]); b.update(k); return b
def T(lines, bg, **k):
    b = dict(talk=[dict(who=w, text=t, **({'mood': m} if m else {})) for w, t, m in [(l + (None,))[:3] for l in lines]], bg=bg); b.update(k); return b

MALL = lambda **k: S('day', shop('CROWN LIQUORS', y=.8), palms(y=.84, n=3, x0=.02, gap=.4, h=380, d=.5), **k)

